theorem abs_coord_sub_le_rho_singlePoint {n k : ℕ} {a b : ℕ → Pt n} {p : ℕ} {i : Fin n}
    (hp : p < k) :
    |a p i - b p i| ≤ rho n k a b

theorem samples_separated (s t : Pt n) (seed : ℕ → Pt n) (k : ℕ) {ρ : ℝ}
    (h : ρ ≤ sqDistAt s t) :
    ρ ≤ sqDistAt (translateBy s seed k) (translateBy t seed k)
